<script setup>
import {computed,onMounted,reactive,ref} from 'vue'
import {api} from './api'
const props=defineProps({channel:{type:String,default:'both'}})
const campaigns=ref([]),selected=ref(null),fields=ref([]),error=ref(''),success=ref(''),saving=ref(false)
const form=reactive({name:'',description:'',status:'draft',channel_scope:'both'})
const q=reactive({id:null,question_text:'',title:'',answer_key:'',reply_type:'text',required:true,capture_field_id:'',config:{choices:[]}})
const choiceMode=computed(()=>q.reply_type==='choice'||q.reply_type==='multiple_choice')
function resetQ(){Object.assign(q,{id:null,question_text:'',title:'',answer_key:'',reply_type:'text',required:true,capture_field_id:'',config:{choices:[]}})}
async function load(){try{[campaigns.value,fields.value]=await Promise.all([api.campaigns(),api.contactFields()]);if(selected.value){const found=campaigns.value.find(x=>x.id===selected.value.id);if(found)await open(found)}}catch(e){error.value=e.message}}
async function open(item){selected.value=await api.campaign(item.id);Object.assign(form,{name:selected.value.name,description:selected.value.description||'',status:selected.value.status,channel_scope:selected.value.channel_scope});resetQ();error.value='';success.value=''}
async function createCampaign(){const name=prompt('Campaign name');if(!name)return;try{const row=await api.createCampaign({name,description:'',status:'draft',channel_scope:'both'});campaigns.value.push(row);await open(row)}catch(e){error.value=e.message}}
async function saveCampaign(){if(!selected.value)return;saving.value=true;try{selected.value=await api.updateCampaign(selected.value.id,{...form});success.value='Campaign saved.';await load()}catch(e){error.value=e.message}finally{saving.value=false}}
function editQuestion(item){Object.assign(q,{id:item.id,question_text:item.question_text,title:item.title||'',answer_key:item.answer_key||'',reply_type:item.reply_type||'text',required:item.required!==false,capture_field_id:item.capture_field_id||'',config:JSON.parse(JSON.stringify(item.config||{}))});if(!Array.isArray(q.config.choices))q.config.choices=[]}
function addChoice(){q.config.choices.push({label:'',value:''})}
async function saveQuestion(){if(!selected.value||!q.question_text.trim())return;const payload={question_text:q.question_text,title:q.title||null,answer_key:q.answer_key||null,reply_type:q.reply_type,required:q.required,capture_field_id:q.capture_field_id?Number(q.capture_field_id):null,config:q.config};try{if(q.id)await api.updateCampaignQuestion(selected.value.id,q.id,payload);else await api.addCampaignQuestion(selected.value.id,payload);await open(selected.value);success.value='Question saved.'}catch(e){error.value=e.message}}
async function removeQuestion(item){if(!confirm(`Delete “${item.question_text}”?`))return;try{await api.deleteCampaignQuestion(selected.value.id,item.id);await open(selected.value)}catch(e){error.value=e.message}}
async function move(item,delta){const list=[...selected.value.questions],i=list.findIndex(x=>x.id===item.id),j=i+delta;if(j<0||j>=list.length)return;[list[i],list[j]]=[list[j],list[i]];try{selected.value.questions=await api.reorderCampaignQuestions(selected.value.id,list.map(x=>x.id))}catch(e){error.value=e.message}}
onMounted(load)
</script>
<template><section class="campaign-page"><header><div><p class="eyebrow">Reusable questionnaires</p><h1>Campaigns</h1><p>Create a questionnaire once and run it from any WhatsApp or Telegram flow.</p></div><button class="primary" @click="createCampaign">+ New campaign</button></header><div v-if="error" class="notice error">{{error}}</div><div v-if="success" class="notice">{{success}}</div><div class="campaign-layout"><aside><button v-for="item in campaigns" :key="item.id" :class="{active:selected?.id===item.id}" @click="open(item)"><b>{{item.name}}</b><span>{{item.question_count}} questions · {{item.status}}</span></button><p v-if="!campaigns.length">No campaigns yet.</p></aside><main v-if="selected"><div class="card campaign-meta"><label>Name<input v-model="form.name"></label><label>Description<textarea v-model="form.description" rows="2"></textarea></label><div class="two"><label>Status<select v-model="form.status"><option value="draft">Draft</option><option value="active">Active</option><option value="paused">Paused</option></select></label><label>Channels<select v-model="form.channel_scope"><option value="both">WhatsApp + Telegram</option><option value="whatsapp">WhatsApp</option><option value="telegram">Telegram</option></select></label></div><button class="primary" :disabled="saving" @click="saveCampaign">Save campaign</button></div><div class="questions"><h2>Questions</h2><article v-for="item in selected.questions" :key="item.id"><span class="order">{{item.sort_order}}</span><div><b>{{item.question_text}}</b><small>{{item.reply_type}} · %input.{{item.answer_key}}%</small></div><button @click="move(item,-1)">↑</button><button @click="move(item,1)">↓</button><button @click="editQuestion(item)">Edit</button><button class="danger" @click="removeQuestion(item)">×</button></article></div><div class="card question-editor"><h2>{{q.id?'Edit':'Add'}} question</h2><label>Question<input v-model="q.question_text" placeholder="Have you greeted the manager?"></label><div class="two"><label>Answer key<input v-model="q.answer_key" placeholder="greeted_manager"></label><label>Reply type<select v-model="q.reply_type"><option value="text">Text</option><option value="email">Email address</option><option value="phone">Phone number (typed)</option><option value="telegram_phone">Telegram — Share phone number</option><option value="date">Date</option><option value="number">Number</option><option value="integer">Whole number</option><option value="decimal">Decimal number</option><option value="image">Photo / image</option><option value="audio">Audio / voice note</option><option value="video">Video</option><option value="document">Document / file</option><option value="sticker">Sticker</option><option value="media">Any media</option><option value="choice">Multiple choice</option></select></label></div><label class="check"><input v-model="q.required" type="checkbox"> Reply required</label><label>Save valid reply to<select v-model="q.capture_field_id"><option value="">Do not save reply</option><option v-for="f in fields" :key="f.id" :value="f.id">{{f.label||f.name||f.key}}</option></select></label><div v-if="choiceMode" class="choice-box"><b>Choices</b><div v-for="(choice,i) in q.config.choices" :key="i" class="choice-row"><input v-model="choice.label" placeholder="Label"><input v-model="choice.value" placeholder="Stored value"><button @click="q.config.choices.splice(i,1)">×</button></div><button @click="addChoice">+ Add choice</button></div><div class="actions"><button class="primary" @click="saveQuestion">{{q.id?'Update':'Add'}} question</button><button v-if="q.id" @click="resetQ">Cancel</button></div></div></main><div v-else class="empty">Select a campaign or create a new one.</div></div></section></template>
<style scoped>.campaign-page{margin-left:220px;min-height:100vh;padding:32px 38px;background:#f4f7f6}.campaign-page>header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:22px}.campaign-page h1{margin:2px 0 5px;font-size:30px}.campaign-page header p:last-child{margin:0;color:#74867e}.eyebrow{margin:0;text-transform:uppercase;color:#119052;font-size:11px;font-weight:800;letter-spacing:.08em}.primary{border:0;background:#168653;color:white;border-radius:8px;padding:10px 14px;font-weight:700}.campaign-layout{display:grid;grid-template-columns:270px minmax(0,1fr);gap:20px}.campaign-layout>aside{display:flex;flex-direction:column;gap:7px}.campaign-layout>aside button{text-align:left;border:1px solid #dce5e1;background:#fff;border-radius:10px;padding:12px}.campaign-layout>aside button.active{border-color:#168653;background:#f2fbf6}.campaign-layout>aside b,.campaign-layout>aside span{display:block}.campaign-layout>aside span{font-size:11px;color:#778981;margin-top:4px}.card{background:#fff;border:1px solid #dfe7e3;border-radius:13px;padding:18px;margin-bottom:18px}.card label{display:flex;flex-direction:column;gap:5px;font-size:12px;font-weight:700;margin-bottom:12px}.card input,.card textarea,.card select{border:1px solid #d5e0db;border-radius:8px;padding:9px;background:#fff}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.questions h2,.question-editor h2{font-size:18px}.questions article{display:grid;grid-template-columns:32px minmax(0,1fr) auto auto auto auto;align-items:center;gap:7px;background:#fff;border:1px solid #dfe7e3;border-radius:10px;padding:10px;margin-bottom:7px}.questions article small{display:block;color:#7b8d85;margin-top:3px}.questions button,.choice-row button,.actions button,.choice-box>button{border:1px solid #d6e0dc;background:#fff;border-radius:7px;padding:7px 9px}.order{font-weight:800;color:#168653}.danger{color:#a33}.check{flex-direction:row!important}.check input{width:auto}.choice-box{border:1px solid #e0e8e4;border-radius:9px;padding:12px;margin-bottom:12px}.choice-row{display:grid;grid-template-columns:1fr 1fr auto;gap:7px;margin:8px 0}.actions{display:flex;gap:8px}.notice{padding:10px 12px;background:#eaf8f0;border-radius:8px;margin-bottom:12px}.notice.error{background:#fff0f0;color:#9c2929}.empty{background:#fff;border:1px dashed #ccd9d3;border-radius:12px;padding:30px;color:#74867e}@media(max-width:900px){.campaign-layout{grid-template-columns:1fr}.two{grid-template-columns:1fr}}</style>